/* data.voucher carries everything needed to deliver.
 * Turn its base64 into a real binary, once, for all three consumers. */
const v = $('Reservation confirmed').first().json.body.data.voucher;

if (!v.pdfBase64) {
  throw new Error(
    'No PDF in the payload. Tick "Also attach a ready-made PDF" in ' +
    'Fidato -> Admin -> Integrations and save, then create a booking.'
  );
}

return [{
  json: { filename: v.filename, reference: v.reference, to: v.to },
  binary: {
    data: {
      data: v.pdfBase64,
      mimeType: 'application/pdf',
      fileName: v.filename,
    },
  },
}];

/* ══════════════════════════════════════════════════════════════
   BUILD THE TEMPLATE COMPONENTS

   The approved template has a document header and 8 body variables:
     name_1  hotel_id  hotel  ck_in  ck_out  rm_type  no_guest  crs_nom

   ⚠️ NAMED OR POSITIONAL — CHECK BEFORE THE FIRST SEND.
   Meta supports both, and they are NOT interchangeable: sending
   `parameter_name` to a positional template fails, and omitting it on
   a named one fails too. Open WhatsApp Manager → Message Templates and
   look at the body:
       {{name_1}}  → named      → USE_NAMED = true
       {{1}}       → positional → USE_NAMED = false
   Your screenshot shows {{name_1}}, so this defaults to named.

   ⚠️ Meta rejects an EMPTY parameter, and rejects newlines, tabs or
   runs of four spaces inside one — with a generic error that names
   none of them. Everything is coalesced and flattened below.
   ══════════════════════════════════════════════════════════════ */

const USE_NAMED = true;

const d = $('Reservation confirmed').first().json.body.data;
const v = d.voucher;
const m = v.model;
const mediaId = $('Upload PDF to Meta').first().json.id;

if (!mediaId) {
  throw new Error('Meta did not return a media id. Check the phone number id and token.');
}

const clean = (value, fallback = '-') => {
  const text = String(value ?? '')
    .replace(/[\r\n\t]+/g, ' ')
    .replace(/\s{4,}/g, ' ')
    .trim();
  return text === '' ? fallback : text;
};

/* One booking can hold several room types and the template has one
   slot, so they are joined rather than silently showing the first. */
const roomType = (m.rooms || [])
  .map((r) => `${r.quantity} x ${r.roomType}`)
  .join(', ');

const guests =
  `${m.totalAdults} adult${m.totalAdults === 1 ? '' : 's'}` +
  (m.totalChildren ? `, ${m.totalChildren} child${m.totalChildren === 1 ? '' : 'ren'}` : '');

/* ⚠️ org.phone is blank on a fresh deployment and an empty parameter
   fails the whole send. Put the real number in Admin → Settings; this
   only stops a silent failure. */
const crsNumber = clean(m.org?.phone, '+91 20 1234 5678');

/* Order matches the template exactly. On a positional template this
   IS the mapping — reorder it and every guest gets a reference where
   their name should be, with no error raised. */
const values = [
  ['name_1',   clean(m.guestName)],
  ['hotel_id', clean(v.reference)],
  ['hotel',    clean(m.hotelName)],
  ['ck_in',    clean(m.checkIn)],
  ['ck_out',   clean(m.checkOut)],
  ['rm_type',  clean(roomType)],
  ['no_guest', clean(guests)],
  ['crs_nom',  crsNumber],
];

const bodyParameters = values.map(([name, text]) =>
  USE_NAMED
    ? { type: 'text', parameter_name: name, text }
    : { type: 'text', text },
);

/* ⚠️ Digits only, no leading +. Meta rejects a `to` containing one. */
const digits = String(v.guestPhone || '').replace(/\D/g, '');
const to = digits.length === 10 ? `91${digits}` : digits;
if (to.length < 11) {
  throw new Error(
    `Guest phone "${v.guestPhone}" is not a usable number. WhatsApp will reject it.`
  );
}

return [{
  json: {
    to,
    reference: v.reference,
    payload: {
      messaging_product: 'whatsapp',
      recipient_type: 'individual',
      to,
      type: 'template',
      template: {
        name: 'REPLACE_WITH_TEMPLATE_NAME',
        language: { code: 'en' },
        components: [
          {
            type: 'header',
            parameters: [
              {
                type: 'document',
                document: { id: mediaId, filename: v.filename },
              },
            ],
          },
          { type: 'body', parameters: bodyParameters },
        ],
      },
    },
  },
}];
